// ---- host logic: examples/api_tours/paint/host.cpp ----
// API tour (C++ Wrapper): host painting into custom elements. Same page, checks and case as
// examples/c/ports/kui_api_paint.c (and the Go / Rust ports): before the page loads the host
// defines six custom elements with a paint callback (CustomElementRegistry::define); each callback
// draws one group of DisplayList calls into its content box. Once frames have run, the host checks
// the callbacks ran with the element's size and every call succeeded, asks for repaints
// (Element::markNeedsPaint / invalidateRect) and checks they arrive; #tour-result ends as
// "PASS n/n". What is drawn is checked by the case's pixel steps; the buttons change it.
//
// Wrapper shapes that differ from the C port:
//   * kui_paint_get_info has no public method: the Wrapper calls it inside its paint trampoline and
//     hands the result over as PaintContext::contentWidth / contentHeight / devicePixelRatio, which
//     is what "paint_get_info.size" checks.
//   * A DisplayList call that fails throws kui::Error (status() is the C status); each call is
//     wrapped so one failure is counted and the rest of the pane still draws.
//   * CustomElementRegistry::define returns false for a second definition; the C status
//     (KUI_ERR_INVALID_ARG) is not exposed.

#include <cstdint>
#include <cstdio>
#include <fstream>
#include <functional>
#include <sstream>

namespace {

kui::Document* g_doc = nullptr;

// ---- Self-check bookkeeping: count, log one <tr> per check, publish the verdict ----------

int g_total = 0;
int g_failed = 0;
std::string g_failed_names;

template <typename... Parts>
std::string cat(const Parts&... parts) {
    std::ostringstream out;
    out.setf(std::ios::fixed);
    out.precision(0);
    (out << ... << parts);
    return out.str();
}

void log_row(const std::string& name, const std::string& result, const std::string& cell) {
    kui::Element* log = g_doc->getElementById("tour-log");
    if (!log) return;
    auto row = g_doc->createElement("tr");
    row->setAttribute("data-check", name);
    row->setAttribute("data-result", result);
    if (result != "ok") row->addClass("bad");
    auto first = g_doc->createElement("td");
    first->setTextContent(name);
    row->appendChild(first);
    auto second = g_doc->createElement("td");
    second->setTextContent(cell);
    row->appendChild(second);
    log->appendChild(row);
}

void check(const std::string& name, bool ok, const std::string& detail) {
    g_total++;
    if (ok) {
        log_row(name, "ok", "ok");
        return;
    }
    g_failed++;
    g_failed_names += (g_failed_names.empty() ? "" : ", ") + name;
    std::fprintf(stderr, "tour check failed: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "fail", "FAIL: " + detail);
}

void finish() {
    kui::Element* result = g_doc->getElementById("tour-result");
    if (!result) return;
    const std::string text = g_failed == 0 ? cat("PASS ", g_total, "/", g_total)
                                           : cat("FAIL ", g_failed, "/", g_total, ": ", g_failed_names);
    result->setTextContent(text);
    result->setAttribute("data-total", std::to_string(g_total));
    result->setAttribute("data-failed", std::to_string(g_failed));
    result->setAttribute("data-known", "0");
    result->addClass(g_failed == 0 ? "pass" : "fail");
}

void set_text(const char* id, const std::string& text) {
    if (kui::Element* element = g_doc->getElementById(id)) element->setTextContent(text);
}

// ---- What the panes draw (the buttons change these) and what the callbacks saw ------------

enum { SHAPES, TEXT, IMAGE, CLIP, XFORM, ALPHA, PANES };
const char* const k_tags[PANES] = {"paint-shapes", "paint-text", "paint-image",
                                   "paint-clip", "paint-xform", "paint-alpha"};
const char* const k_ids[PANES] = {"pv-shapes", "pv-text", "pv-image", "pv-clip", "pv-xform", "pv-alpha"};

int g_paints[PANES] = {};        // paint callback calls
float g_width[PANES] = {};       // PaintContext content size, last call
float g_height[PANES] = {};
float g_dpr[PANES] = {};
int g_bad_calls[PANES] = {};     // DisplayList calls that threw
KuiStatus g_unbalanced = KUI_OK; // restore without save, tried once
bool g_unbalanced_tried = false;

kui::Color g_fill(0xef, 0x44, 0x44);  // shapes: first rectangle
int g_line_style = 0;                 // text: decoration style (0 solid .. 4 wavy)
kui::Color g_line(0xe1, 0x1d, 0x48);  // text: decoration line colour
int g_pixel_shift = 0;                // image: rotates the 2x2 buffer
bool g_clip_on = true;
float g_angle = 45.0f;
float g_alpha = 0.5f;
std::string g_image_path;

const char* const k_style_names[] = {"solid", "double", "dotted", "dashed", "wavy"};

bool same(const kui::Color& a, const kui::Color& b) { return a == b; }

// Runs one DisplayList call; a call that throws is counted against its pane.
template <typename Fn>
void ok(int pane, Fn&& fn) {
    try {
        fn();
    } catch (const kui::Error&) {
        g_bad_calls[pane]++;
    }
}

// ---- Paint callbacks: one group of calls per pane -----------------------------------------

// Filled and stroked rectangles at fixed fractions of the width (the case samples them).
void paint_shapes(kui::DisplayList& d, float w, float h) {
    ok(SHAPES, [&] { d.fillRect({0.03f * w, 0.15f * h, 0.20f * w, 0.70f * h}, g_fill); });
    ok(SHAPES, [&] {
        d.fillRoundedRect({0.28f * w, 0.15f * h, 0.20f * w, 0.70f * h}, kui::CornerRadii(16.0f),
                          kui::Color(0x22, 0xc5, 0x5e));
    });
    ok(SHAPES, [&] { d.strokeRect({0.53f * w, 0.15f * h, 0.20f * w, 0.70f * h}, kui::Color(0x3b, 0x82, 0xf6), 8.0f); });
    ok(SHAPES, [&] {
        d.strokeRoundedRect({0.78f * w, 0.15f * h, 0.19f * w, 0.70f * h}, kui::CornerRadii(14.0f),
                            kui::Color(0xa8, 0x55, 0xf7), 8.0f);
    });
}

// Bold text hanging from y (the top of its line box, not the baseline), the decoration line band at 0.6h..0.6h+8 and a wavy line below.
void paint_text(kui::DisplayList& d, float w, float h) {
    ok(TEXT, [&] {
        d.drawText("Hello paint", {10.0f, 0.45f * h}, "sans-serif", 26.0f, 700, 0, kui::Color(0x0f, 0x17, 0x2a));
    });
    ok(TEXT, [&] { d.drawDecorationLine(10.0f, 0.6f * h, 0.9f * w, 8.0f, static_cast<kui::u8>(g_line_style), g_line); });
    ok(TEXT, [&] { d.drawDecorationLine(10.0f, 0.82f * h, 0.9f * w, 2.0f, 4, kui::Color(0x0e, 0xa5, 0xe9)); });
}

// A 2x2 premultiplied 0xAARRGGBB buffer scaled into the left box, an image file into the right.
void paint_image(kui::DisplayList& d, float w, float h) {
    static const std::uint32_t colors[4] = {0xffff0000u, 0xff00ff00u, 0xff0000ffu, 0xffffff00u};
    std::uint32_t pixels[4];
    for (int index = 0; index < 4; ++index) pixels[index] = colors[(index + g_pixel_shift) % 4];
    ok(IMAGE, [&] { d.drawPixelBuffer(pixels, 2, 2, {0.03f * w, 0.1f * h, 0.4f * w, 0.8f * h}); });
    ok(IMAGE, [&] { d.drawImage(g_image_path, {0, 0, 8, 8}, {0.55f * w, 0.1f * h, 0.4f * w, 0.8f * h}); });
}

// Top band clipped to the left half; bottom band clipped to a rounded rectangle.
void paint_clip(kui::DisplayList& d, float w, float h) {
    ok(CLIP, [&] { d.save(); });
    if (g_clip_on) ok(CLIP, [&] { d.clipRect({0, 0, 0.5f * w, h}); });
    ok(CLIP, [&] { d.fillRect({0, 0, w, 0.45f * h}, kui::Color(0xf9, 0x73, 0x16)); });
    ok(CLIP, [&] { d.restore(); });
    ok(CLIP, [&] { d.save(); });
    if (g_clip_on) ok(CLIP, [&] { d.clipRoundedRect({0.1f * w, 0.55f * h, 0.8f * w, 0.4f * h}, kui::CornerRadii(24.0f)); });
    ok(CLIP, [&] { d.fillRect({0, 0.5f * h, w, 0.5f * h}, kui::Color(0x14, 0xb8, 0xa6)); });
    ok(CLIP, [&] { d.restore(); });
}

// A 60x60 square rotated about (0.25w, 0.5h); a 10x10 square scaled x4 at (0.6w, 0.2h); after the
// last restore a marker in the bottom-right corner (it lands there only if the transforms were undone).
void paint_xform(kui::DisplayList& d, float w, float h) {
    ok(XFORM, [&] { d.save(); });
    ok(XFORM, [&] { d.translate(0.25f * w, 0.5f * h); });
    ok(XFORM, [&] { d.rotate(g_angle); });
    ok(XFORM, [&] { d.fillRect({-30, -30, 60, 60}, kui::Color(0x63, 0x66, 0xf1)); });
    ok(XFORM, [&] { d.restore(); });
    ok(XFORM, [&] { d.save(); });
    ok(XFORM, [&] { d.translate(0.6f * w, 0.2f * h); });
    ok(XFORM, [&] { d.scale(4, 4); });
    ok(XFORM, [&] { d.fillRect({0, 0, 10, 10}, kui::Color(0xf5, 0x9e, 0x0b)); });
    ok(XFORM, [&] { d.restore(); });
    ok(XFORM, [&] { d.fillRect({w - 20, h - 20, 16, 16}, kui::Color(0x16, 0xa3, 0x4a)); });
    if (!g_unbalanced_tried) {
        // kui_c.h: restore without a matching save is KUI_ERR_INVALID_ARG (thrown as kui::Error).
        g_unbalanced_tried = true;
        try {
            d.restore();
            g_unbalanced = KUI_OK;
        } catch (const kui::Error& error) {
            g_unbalanced = error.status();
        }
    }
}

// Blue at g_alpha on the left; 0.5 inside 0.5 on the right.
void paint_alpha(kui::DisplayList& d, float w, float h) {
    const kui::Color blue(0x00, 0x00, 0xff);
    ok(ALPHA, [&] { d.save(); });
    ok(ALPHA, [&] { d.setOpacity(g_alpha); });
    ok(ALPHA, [&] { d.fillRect({0.05f * w, 0.15f * h, 0.4f * w, 0.7f * h}, blue); });
    ok(ALPHA, [&] { d.restore(); });
    ok(ALPHA, [&] { d.save(); });
    ok(ALPHA, [&] { d.setOpacity(0.5f); });
    ok(ALPHA, [&] { d.save(); });
    ok(ALPHA, [&] { d.setOpacity(0.5f); });
    ok(ALPHA, [&] { d.fillRect({0.55f * w, 0.15f * h, 0.4f * w, 0.7f * h}, blue); });
    ok(ALPHA, [&] { d.restore(); });
    ok(ALPHA, [&] { d.restore(); });
}

void on_paint(int pane, kui::CustomElementDefinition::PaintContext& ctx) {
    const float w = ctx.contentWidth;
    const float h = ctx.contentHeight;
    g_paints[pane]++;
    g_width[pane] = w;
    g_height[pane] = h;
    g_dpr[pane] = ctx.devicePixelRatio;
    if (!ctx.displayList) {
        g_bad_calls[pane]++;
        return;
    }
    kui::DisplayList& d = *ctx.displayList;
    switch (pane) {
        case SHAPES: paint_shapes(d, w, h); break;
        case TEXT: paint_text(d, w, h); break;
        case IMAGE: paint_image(d, w, h); break;
        case CLIP: paint_clip(d, w, h); break;
        case XFORM: paint_xform(d, w, h); break;
        default: paint_alpha(d, w, h); break;
    }
}

// ---- Before the page loads: the image file and the six definitions -----------------------

void put_u32(unsigned char* at, std::uint32_t value) {
    at[0] = static_cast<unsigned char>(value);
    at[1] = static_cast<unsigned char>(value >> 8);
    at[2] = static_cast<unsigned char>(value >> 16);
    at[3] = static_cast<unsigned char>(value >> 24);
}

// An 8x8 24-bit BMP filled with #14b8a6 (teal).
bool write_image() {
    std::string dir = tour_env("TEMP");
    if (dir.empty()) dir = tour_env("TMPDIR");
    if (dir.empty()) dir = "/tmp";
    g_image_path = dir + "/kui_api_paint_cpp.bmp";
    unsigned char header[54] = {};
    unsigned char row[24];
    header[0] = 'B';
    header[1] = 'M';
    put_u32(header + 2, 54 + 8 * 24);
    put_u32(header + 10, 54);
    put_u32(header + 14, 40);
    put_u32(header + 18, 8);
    put_u32(header + 22, 8);
    header[26] = 1;   // planes
    header[28] = 24;  // bits per pixel
    put_u32(header + 34, 8 * 24);
    for (int index = 0; index < 8; ++index) {  // blue, green, red
        row[index * 3] = 0xa6;
        row[index * 3 + 1] = 0xb8;
        row[index * 3 + 2] = 0x14;
    }
    std::ofstream file(g_image_path, std::ios::binary);
    if (!file) return false;
    file.write(reinterpret_cast<const char*>(header), sizeof header);
    for (int index = 0; index < 8; ++index) file.write(reinterpret_cast<const char*>(row), sizeof row);
    return static_cast<bool>(file);
}

kui::CustomElementDefinition definition_for(int pane) {
    kui::CustomElementDefinition definition;
    definition.tagName = k_tags[pane];
    definition.paintCallback = [pane](kui::CustomElementDefinition::PaintContext& ctx) { on_paint(pane, ctx); };
    return definition;
}

// ---- Self-check: definitions now, callbacks and repaints once frames have run -----------

int g_marks[PANES] = {};

kui::Rect bounding(int pane) {
    kui::Element* element = g_doc->getElementById(k_ids[pane]);
    return element ? element->boundingClientRect() : kui::Rect{};
}

void check_definitions() {
    kui::CustomElementRegistry* registry = g_doc->customElements();
    bool all = registry != nullptr;
    for (int pane = 0; all && pane < PANES; ++pane) all = registry->isDefined(k_tags[pane]);
    const bool second = registry && registry->define("paint-shapes", definition_for(SHAPES));
    check("define_custom_element_ex", all && !second,
          cat("all defined ", all, ", second definition accepted ", second));
}

void phase_repainted() {
    check("request_repaint", g_paints[SHAPES] > g_marks[SHAPES],
          cat("paints ", g_marks[SHAPES], " -> ", g_paints[SHAPES]));
    check("invalidate_rect", g_paints[TEXT] > g_marks[TEXT], cat("paints ", g_marks[TEXT], " -> ", g_paints[TEXT]));
    finish();
}

void phase_painted() {
    std::string sizes;
    bool all_painted = true;
    bool sizes_match = true;
    int bad = 0;
    for (int pane = 0; pane < PANES; ++pane) {
        const kui::Rect rect = bounding(pane);
        all_painted = all_painted && g_paints[pane] > 0;
        sizes_match = sizes_match && g_dpr[pane] > 0 && rect.width > 0 && g_width[pane] > rect.width - 0.5f &&
                      g_width[pane] < rect.width + 0.5f && g_height[pane] > rect.height - 0.5f &&
                      g_height[pane] < rect.height + 0.5f;
        sizes += cat(pane ? " " : "", g_width[pane], "x", g_height[pane], "/", rect.width, "x", rect.height);
        bad += g_bad_calls[pane];
    }
    check("paint.callbacks_run", all_painted,
          cat("paints ", g_paints[0], ",", g_paints[1], ",", g_paints[2], ",", g_paints[3], ",", g_paints[4], ",",
              g_paints[5]));
    check("paint_get_info.size", sizes_match, cat("info/element ", sizes, ", dpr ", g_dpr[0]));
    check("paint.calls_ok", bad == 0, cat(bad, " calls did not return KUI_OK"));
    check("paint_restore.unbalanced", g_unbalanced_tried && g_unbalanced == KUI_ERR_INVALID_ARG,
          cat("tried ", g_unbalanced_tried, " status ", static_cast<int>(g_unbalanced)));

    for (int pane = 0; pane < PANES; ++pane) g_marks[pane] = g_paints[pane];
    if (kui::Element* element = g_doc->getElementById("pv-shapes")) element->markNeedsPaint();
    if (kui::Element* element = g_doc->getElementById("pv-text")) element->invalidateRect({0, 60, 300, 20});
    kui::Platform::setTimeout([] { phase_repainted(); }, 300);
}

// ---- Panel buttons: change what a pane draws, then ask for its repaint -------------------

void repaint(int pane) {
    if (kui::Element* element = g_doc->getElementById(k_ids[pane])) element->markNeedsPaint();
}

// Repaints only the decoration line's band of the text pane.
void invalidate_line() {
    kui::Element* element = g_doc->getElementById("pv-text");
    const float h = g_height[TEXT] > 0 ? g_height[TEXT] : 120.0f;
    const float w = g_width[TEXT] > 0 ? g_width[TEXT] : 300.0f;
    if (element) element->invalidateRect({0, 0.6f * h - 2, w, 12});
}

const kui::Color k_red(0xef, 0x44, 0x44);
const kui::Color k_orange(0xf9, 0x73, 0x16);
const kui::Color k_rose(0xe1, 0x1d, 0x48);
const kui::Color k_blue(0x25, 0x63, 0xeb);

void on_shapes_color() {
    g_fill = same(g_fill, k_red) ? k_orange : k_red;
    repaint(SHAPES);
    set_text("shapes-out", same(g_fill, k_red) ? "fill=#ef4444" : "fill=#f97316");
}

void on_paint_info() {
    char dpr[16];
    std::snprintf(dpr, sizeof dpr, "%.2f", static_cast<double>(g_dpr[SHAPES]));
    set_text("shapes-out", cat("paints=", g_paints[0], ",", g_paints[1], ",", g_paints[2], ",", g_paints[3], ",",
                               g_paints[4], ",", g_paints[5], " | ", g_width[SHAPES], "x", g_height[SHAPES], " @", dpr));
}

void on_text_style() {
    g_line_style = (g_line_style + 1) % 5;
    invalidate_line();
    set_text("text-out", cat("style=", k_style_names[g_line_style]));
}

void on_text_color() {
    g_line = same(g_line, k_rose) ? k_blue : k_rose;
    invalidate_line();
    set_text("text-out", same(g_line, k_rose) ? "line=#e11d48" : "line=#2563eb");
}

void on_image_rotate() {
    static const char* const names[4] = {"#ff0000", "#00ff00", "#0000ff", "#ffff00"};
    g_pixel_shift = (g_pixel_shift + 1) % 4;
    repaint(IMAGE);
    set_text("image-out", cat("top-left=", names[g_pixel_shift]));
}

void on_clip_toggle() {
    g_clip_on = !g_clip_on;
    repaint(CLIP);
    set_text("clip-out", g_clip_on ? "clip=on" : "clip=off");
}

void on_xform_rotate() {
    g_angle = g_angle == 0.0f ? 45.0f : 0.0f;
    repaint(XFORM);
    set_text("xform-out", cat("angle=", g_angle));
}

void on_alpha_cycle() {
    char text[32];
    g_alpha = g_alpha == 0.5f ? 1.0f : (g_alpha == 1.0f ? 0.25f : 0.5f);
    repaint(ALPHA);
    std::snprintf(text, sizeof text, "opacity=%g", static_cast<double>(g_alpha));
    set_text("alpha-out", text);
}

// Clicks on #id run `handler` (a missing button is reported as a failed check).
void on_click(const char* id, void (*handler)()) {
    kui::Element* button = g_doc->getElementById(id);
    if (!button) {
        check(cat("ui.", id), false, "button missing");
        return;
    }
    button->addEventListener("click", [handler](kui::Event&) { handler(); });
}

}  // namespace

void tour_before_load(kui::Window& window, kui::Document& document) {
    (void)window;
    if (!write_image()) std::fprintf(stderr, "kui_api_paint: cannot write %s\n", g_image_path.c_str());
    kui::CustomElementRegistry* registry = document.customElements();
    for (int pane = 0; pane < PANES; ++pane) {
        if (!registry || !registry->define(k_tags[pane], definition_for(pane)))
            std::fprintf(stderr, "kui_api_paint: cannot define <%s>\n", k_tags[pane]);
    }
}

void tour_ready(kui::Window& window, kui::Document& document) {
    (void)window;
    g_doc = &document;

    check_definitions();
    // Paint callbacks run with frames: check them once a few have been drawn.
    kui::Platform::setTimeout([] { phase_painted(); }, 500);

    on_click("btn-shapes-color", on_shapes_color);
    on_click("btn-paint-info", on_paint_info);
    on_click("btn-text-style", on_text_style);
    on_click("btn-text-color", on_text_color);
    on_click("btn-image-rotate", on_image_rotate);
    on_click("btn-clip-toggle", on_clip_toggle);
    on_click("btn-xform-rotate", on_xform_rotate);
    on_click("btn-alpha-cycle", on_alpha_cycle);
}
// ---- end of examples/api_tours/paint/host.cpp ----

int main() {
    try {
        if (!kui::Platform::init()) return 3;
        kui::WindowConfig config;
        config.title = "KUI API \xe2\x80\x94 custom paint";
        config.width = 1100;
        config.height = 780;
        auto window = kui::Window::create(config);
        if (!window) return 4;
        kui::Document* document = window->document();
        auto script = kui::ScriptEngine::create();
        if (script) {
            script->setErrorHandler([](const std::string& error, const std::string& source, int line) {
                std::fprintf(stderr, "[Lua] %s:%d: %s\n", source.c_str(), line, error.c_str());
            });
            script->bindDocument(document);
            window->setScriptEngine(script.get());
        }
        tour_script = script.get();
        tour_before_load(*window, *document);
        document->loadHTML(k_tour_page);
        if (script) script->executeScripts();
        // Test hook shared with the C / Go / Rust runners: KUI_EXAMPLE_DEVTOOLS_PORT=<port> starts
        // DevTools so scripts/verify_example_ports.py can click and read the DOM.
        const std::string port = tour_env("KUI_EXAMPLE_DEVTOOLS_PORT");
        if (!port.empty()) window->startDevTools(static_cast<kui::u16>(std::atoi(port.c_str())));
        tour_ready(*window, *document);
        const int code = kui::Platform::run();
        tour_script = nullptr;
        return code;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "[kui_api_paint] %s\n", error.what());
        return 9;
    }
}
